$review=Join-Path $tests ('outputs\'+$tag+'_native');$record=Join-Path $logs ($tag+'.native.json');$callPath=Join-Path $logs ($tag+'_reader.call.json');$log=Join-Path $logs ($tag+'_reader.log');$samples=769;$steps=10000;$end=0.025
function E([string]$p){$f=Get-Item -LiteralPath $p;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($e in $rows){Need ($e.path -and $null -ne $e.bytes -and $e.sha256) 'Missing Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed artifact: '+$e.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function N($v){Need ($null -ne $v -and [string]$v -ne '') 'Missing numeric field';$n=if($v -is [ValueType]){[double]$v}else{[double]::Parse([string]$v,[Globalization.CultureInfo]::InvariantCulture)};Need (![double]::IsNaN($n) -and ![double]::IsInfinity($n)) 'Nonfinite numeric field';return $n}
function Owned($entry){V @($entry);$c=J $entry.path;Need ($c.owned_call_exited -and $c.typed_LASTEXITCODE_captured_immediately -and $c.exit_code -is [int] -and $c.exit_code -eq 0 -and !$c.invocation_failure) 'Own immediate typed exit0 required';V @($c.program,$c.log)}
function Bin([string]$leaf,[uint32[]]$header,[long]$payload){$p=Join-Path $review $leaf;$e=E $p;Need ($e.bytes -eq 4L*$header.Count+$payload) ('Binary length differs: '+$leaf);$br=New-Object IO.BinaryReader([IO.File]::OpenRead($p));try{foreach($n in $header){Need ($br.ReadUInt32() -eq $n) ('Binary header differs: '+$leaf)}}finally{$br.Dispose()};return @{file=$e;header=$header;length_verified=$true}}
Fresh @($review,$record,$callPath,$log)
$hp=Join-Path $logs 'upl_column_public_reader_ReleaseCPU_r1.helper.json';$h=J $hp;$b=J $h.source_build.path;$d=J $h.source_freeze.path
Need ($h.passed -and $h.stage -ceq 'upl_column_public_reader_build_r1' -and $h.status -ceq 'current_public_column_CPU_reader_linked_not_run' -and $h.kind -ceq 'reader' -and $h.configuration -ceq 'ReleaseCPU' -and $h.build_and_source_bindings_unchanged -and $h.exact_link_closure_verified -and $h.CPU_non_main_objects -eq 85 -and @($h.objects).Count -eq 85 -and $h.link_object_count -eq 86 -and @($h.libraries).Count -eq 17 -and @($h.runtime).Count -eq 4 -and !$h.program_run -and !$h.solver_started -and !$h.physical_acceptance) 'Real current CPU85+reader helper required'
Need ($b.passed -and $b.configuration -ceq 'ReleaseCPU' -and $b.source_bindings_unchanged -and @($b.objects).Count -eq 86 -and $d.passed -and $d.configuration -ceq 'DebugCPU' -and $d.source_bindings_unchanged -and $d.canonical_programs_unchanged -and $d.runtime_unchanged -and @($d.source_snapshot).Count -eq 265 -and @($d.canonical_programs_before).Count -eq 7 -and @($d.runtime_before).Count -eq 4 -and $h.source_freeze.sha256 -ceq $h.adopted_Debug_source_build.sha256) 'Reader adopted-Debug265/doc/canonical7/runtime4 authority required';Owned $h.compile_call;Owned $h.link_call
$runPath=Join-Path $logs ($tag+'.run.json');$r=J $runPath;$solver=J $r.call.path
Need ($r.passed -and $r.stage -ceq 'upl_column_cost_r1' -and $r.job -ceq $Job -and $r.threads -eq $threads -and $r.configuration -ceq $(if($Backend -ceq 'CPU'){'ReleaseCPU'}else{'Release'}) -and $r.backend -ceq $Backend -and $r.window -ceq $Window -and $r.public_project_main -and !$r.fixture_or_Run_override -and $r.source_inputs_objects_runtime_canonical_unchanged -and $r.all_raw_outputs_hash_bound -and $r.native_frame_sequence_exact -and $r.native_frames -eq $samples -and $r.planned_samples -eq $samples -and $r.planned_steps -eq $steps -and (N $r.planned_dt_s) -eq 2.5e-6 -and (N $r.planned_end_s) -eq $end -and !$r.physical_acceptance) 'Own passed public Run/schedule required';Owned $r.call
Need (@($r.arguments).Count -eq @($solver.target_arguments).Count -and !(@(0..(@($r.arguments).Count-1)|Where-Object{$r.arguments[$_] -cne $solver.target_arguments[$_]}))) 'Sealed actual target argv differs'
if($Backend -ceq 'CPU'){Need (@($r.arguments|Where-Object{$_ -ceq ('-ompthreads:'+$threads)}).Count -eq 1) 'Actual explicit CPU thread request missing'}else{Need (@($r.arguments|Where-Object{$_ -ceq '-gpu:0'}).Count -eq 1) 'Actual GPU request missing'}
Need ($solver.public_project_main -and !$solver.fixture_or_Run_override -and $solver.target_program.sha256 -ceq $r.program.sha256) 'Actual public target program binding differs';
$sourceByPath=@{};foreach($p in $d.source_snapshot){Need (!$sourceByPath.ContainsKey($p.original.path)) 'Duplicate reader source path';$sourceByPath[$p.original.path]=$p.original}
Need (@($r.source_snapshot).Count -eq 265) 'Actual solver source265 required';$seen=@{};foreach($p in $r.source_snapshot){$e=$p.original;Need ($sourceByPath.ContainsKey($e.path) -and !$seen.ContainsKey($e.path)) 'Solver/reader source path membership differs';$a=$sourceByPath[$e.path];Need ($e.bytes -eq $a.bytes -and $e.sha256 -ieq $a.sha256) 'Solver/reader used different current source';$seen[$e.path]=$true}
$data=Join-Path (Split-Path -Parent $r.run_out.path) 'data';Need ($data -ceq (Join-Path $tests ('outputs\'+$tag+'\data'))) 'Only own public raw data admitted'
$inputs=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_column_cost_native_r1.json')),(E $hp),$h.source_build,$h.source_freeze,$h.adopted_Debug_source_build,$h.program,$h.helper_object,$h.compile_call,$h.link_call,$h.compiler_dependency_record,(E $runPath),$r.call,$r.source_build,$r.program,$r.input_manifest,$r.runtime_input)
if($r.source_freeze){$inputs+=@($r.source_freeze)};if($r.adopted_Debug_source_build){$inputs+=@($r.adopted_Debug_source_build)}
function Verify{
  V $inputs;V $h.inputs;V $h.author_files;V $h.tools;V $h.libraries;V $h.objects;V $b.tools;V $d.tools;V $r.inputs;V $r.files;V @($solver.program,$solver.target_program,$solver.log);V $r.canonical_programs_before;V $d.canonical_programs_before;V $d.runtime_before;V @($d.documentation_snapshot.original,$d.documentation_snapshot.snapshot,$r.documentation_snapshot.original,$r.documentation_snapshot.snapshot)
  foreach($p in @($d.source_snapshot)+@($r.source_snapshot)){V @($p.original,$p.snapshot);Need ($p.original.bytes -eq $p.snapshot.bytes -and $p.original.sha256 -ieq $p.snapshot.sha256) 'Current source/snapshot differs'};foreach($p in @($h.runtime)+@($r.runtime)){V @($p.original,$p.copy)}
}
Verify;$argv=@('--read',$Backend,$data,[string]$samples,'0.0000025',$review);[IO.File]::WriteAllBytes($log,[byte[]]@());$start=[DateTime]::UtcNow.ToString('o');$code=$null;$launchFailure=$null;$saved=$ErrorActionPreference
Push-Location $caseRoot;try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $h.program.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$launchFailure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$h.program;arguments=$argv;working_directory=$caseRoot;started_utc=$start;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$launchFailure;log=(E $log);pure_native_reader=$true;solver_or_build_invoked=$false;physical_acceptance=$false})
$failure=$launchFailure;$completion=$null;$done=$null;$files=@();$headers=@();$unchanged=$false
try{
  Need ($code -is [int] -and $code -eq 0 -and !$launchFailure) 'Owned pure reader failed; do not rerun solver';$completion=E (Join-Path $review 'completion.json');$done=J $completion.path
  Need ($done.passed -and $done.stage -ceq 'upl_column_public_native_r1' -and $done.backend -ceq ($Backend+'_public') -and $done.window -ceq $(if($samples -eq 3){'smoke'}else{'window25'}) -and $done.grid -ceq 'c' -and $done.model -ceq 'constant' -and $done.conductivity_model -eq 0 -and (N $done.conductivity_Ck) -eq 0 -and $done.public_schema -and $done.public_master_on -and $done.native_count -eq 1000 -and $done.fixed_count -eq 40 -and $done.total_native_count -eq 1040 -and $done.samples -eq $samples -and $done.physical_columns -eq 26 -and $done.physical_schema -ceq 'case02_common26_col21_ExcessPorePress_NOT_wave26' -and $done.original_typed_arrays -eq 15 -and $done.native_dynamic_double_arrays -eq 6 -and $done.native_total_arrays -eq 22 -and $done.native_PosDiv_present -and $done.native_PosDiv_is_float -and $done.native_V_rho_k_present -and $done.PART_typed_public_metadata_verified) 'Public native schema/backend/count contract rejected'
  Need ((N $done.dt_s) -eq 2.5e-6 -and [Math]::Abs((N $done.actual_end_s)-$end) -le 1e-14 -and $done.planned_completed_steps -eq $steps -and $done.declared_saved_completed_steps_exact -and $done.actual_time_step_locked_dt_exact -and $done.noninitial_signed_dterror_intervals -eq ($samples-1) -and $done.initial_empty_dterror_intervals -in @(0,1) -and $done.initial_dterror_excluded_from_noninitial_summary -and (N $done.max_noninitial_signed_dterror_s) -le 1e-14) 'Original accumulated-clock/Step/signed-diagnostic contract rejected'
  Need ($done.soil_ledger_checks -eq (1000*$samples) -and $done.fixed_public_zero_marker_checks -eq (40*$samples) -and $done.all_native_J_theta_rows -eq (1040*$samples) -and $done.soil_native_n_rows -eq (1000*$samples) -and $done.fixed_J_theta_original15_not_zeroed_or_masked -and (N $done.max_ledger_relative_error) -le 5e-13 -and $done.no_exclusions -and $done.initial_rest_and_decimal_lattice_verified -and $done.double_stress_and_float_display_verified -and $done.all_exported_physical_fields_finite -and !$done.PosDiv_fabricated_or_derived -and $done.common26_column21_is_actual_ExcessPorePress -and $done.post_open_completed_step_threshold -eq 4000 -and $done.pre_open_event_pressure_not_forced_zero -and $done.density_and_J_not_frozen_on_drained_receivers -and $done.post_open_frames -eq $(if($samples -eq 3){0}else{359}) -and !$done.historical_private_comparison_performed_by_reader -and !$done.live_final_compared_by_reader -and !$done.same_force_stage_load_budget_verified -and !$done.independent_half_performed -and !$done.physical_acceptance) 'Original ledger/markers/finite/drain-scope contract rejected'
  Need ($done.GPU_private_fixed_n_mirror_to_public_zero_is_schema_change -eq ($Backend -ceq 'GPU')) 'Fixed marker backend semantics differ'
  Need ($done.post_open_drained_particle_checks -eq $(if($samples -eq 3){0}else{3590}) -and $done.max_activeDrainCount -eq $(if($samples -eq 3){0}else{10})) 'Original nonempty drained-receiver count differs'
  $history=@(Import-Csv -LiteralPath (Join-Path $review 'history.csv'));Need ($history.Count -eq $samples) 'History row count differs';$openFrames=0
  for($i=0;$i -lt $samples;$i++){$row=$history[$i];$completed=N $row.completed_step;$active=N $row.activeDrainCount;$opened=($completed -gt 4000);Need ((N $row.part) -eq $i -and (N $row.post_open_by_completed_step) -eq [int]$opened -and $active -eq $(if($opened){10}else{0})) 'Per-frame original drainage mask empty or inconsistent';$openFrames+=[int]$opened};Need ($openFrames -eq $(if($samples -eq 3){0}else{359})) 'History post-open coverage differs'
  $expected=@('original15.bin','physical.bin','clock.bin','common_j_theta.bin','soil_n.bin','native_ids.csv','fixed_ids.csv','history.csv','ledger.csv','fixed_samples.csv','last_poro.csv','columns.csv','completion.json');$actual=@(Get-ChildItem -LiteralPath $review -File|ForEach-Object{$_.Name});Need ($actual.Count -eq 13 -and !(Compare-Object ($expected|Sort-Object) ($actual|Sort-Object))) 'Exactly13 declared reader output files required'
  $headers+=@(Bin 'original15.bin' @(1040,15,$samples) ([long]$samples*166408));$headers+=@(Bin 'physical.bin' @(1000,26,$samples) ([long]$samples*208008));$headers+=@(Bin 'clock.bin' @($samples,28) ([long]$samples*28));$headers+=@(Bin 'common_j_theta.bin' @(1040,2,$samples) ([long]$samples*16648));$headers+=@(Bin 'soil_n.bin' @(1000,1,$samples) ([long]$samples*8008))
}catch{$failure=$_.Exception.Message}
try{Verify;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}};if(Test-Path -LiteralPath $review){$files=@(Get-ChildItem -LiteralPath $review -File|Sort-Object FullName|ForEach-Object{E $_.FullName})}
$passed=(!$failure -and $unchanged -and $null -ne $done -and $headers.Count -eq 5 -and $code -is [int] -and $code -eq 0)
Save $record ([ordered]@{stage='upl_column_cost_native_r1';passed=[bool]$passed;job=$Job;backend=$Backend;window=$Window;paths=@{native_dir=$review;solver_dir=(Split-Path -Parent $r.run_out.path)};source_run=(E $runPath);reader_helper=(E $hp);reader_source_build=$h.source_build;reader_source_authority=$h.source_freeze;reader_call=(E $callPath);completion=$completion;inputs=$inputs;files=$files;binary_header_length_checks=$headers;source_inputs_raw_objects_runtime_canonical_unchanged=$unchanged;native_samples=$samples;physical_columns=26;public_native_arrays=22;fixed_public_markers_checked_by_reader=([bool]$passed);ledger_CSV_rows_reparsed=0;private_comparison_performed=$false;live_state_comparison_performed=$false;drainage_nonempty_per_frame_independently_verified=([bool]$passed -and $Window -ceq 'coarse');new_solver_or_build_invoked=$false;physical_acceptance=$false;failure=$failure})
